INSERT INTO recipes (id, slug, title, description, cuisine, cook_time_minutes, servings, difficulty, image_url, tags) VALUES
('vn-canh-01', 'canh-chua-ca-loc-nam-bo', 'Canh chua cá lóc Nam Bộ', 'Bát canh chua cá lóc đậm đà vị chua thanh của me, ngọt mát từ dứa, cà chua, đậu bắp và giá đỗ chuẩn vị miền Tây.', 'vietnamese', 25, 4, 'medium', 'https://images.unsplash.com/photo-1541832676-9b763b0239ab?auto=format&fit=crop&w=800&q=80', '["Món canh","Nam Bộ","Thanh nhiệt","Cá tươi","cat:mon_canh","region:nam"]'),
('vn-canh-02', 'canh-cua-dong-rau-day-mong-toi', 'Canh cua đồng mồng tơi mướp hương', 'Món canh giải nhiệt trứ danh mùa hè miền Bắc với tảng riêu cua đồng béo ngậy nấu cùng mồng tơi và mướp hương thanh mát.', 'vietnamese', 20, 4, 'medium', 'https://images.unsplash.com/photo-1547592180-85f173990554?auto=format&fit=crop&w=800&q=80', '["Món canh","Miền Bắc","Mùa hè","Cua đồng","cat:mon_canh","region:bac"]'),
('vn-canh-03', 'canh-kho-qua-nhoi-thit', 'Canh khổ qua nhồi thịt thanh mát', 'Trái khổ qua dồn thịt heo xay ngọt đậm vị, nước dùng ngọt thanh giúp thanh nhiệt giải độc cơ thể.', 'vietnamese', 30, 4, 'medium', 'https://images.unsplash.com/photo-1603105037880-880cd4edfb0d?auto=format&fit=crop&w=800&q=80', '["Món canh","Thanh nhiệt","Truyền thống","Dễ ăn","cat:mon_canh","region:nam"]'),
('vn-canh-04', 'canh-suon-bi-dao', 'Canh sườn hầm bí đao ngọt thanh', 'Sườn heo ninh mềm róc xương kết hợp vị ngọt thanh của bí đao xanh tạo nên món canh dễ ăn cho cả gia đình.', 'vietnamese', 35, 4, 'easy', 'https://images.unsplash.com/photo-1574484284002-952d92456975?auto=format&fit=crop&w=800&q=80', '["Món canh","Bổ dưỡng","Cơm nhà","Trẻ em thích","cat:mon_canh","region:toan_quoc"]'),
('vn-canh-05', 'canh-bi-do-thit-bam', 'Canh bí đỏ thịt bằm hạt sen', 'Bí đỏ bùi bùi sánh mịn cùng thịt băm ngọt đậm đà, bổ sung nhiều vitamin A và dưỡng chất quý giá.', 'vietnamese', 20, 4, 'easy', 'https://images.unsplash.com/photo-1547592166-23ac45744acd?auto=format&fit=crop&w=800&q=80', '["Món canh","Bổ não","Nhanh gọn","Dưới 20 phút","cat:mon_canh","region:toan_quoc"]'),
('vn-canh-06', 'canh-ngao-nau-chua-thi-la', 'Canh ngao nấu chua thì là', 'Vị ngọt thanh khiết của ngao hòa cùng vị chua dịu của dứa, cà chua và hương thơm đặc trưng của rau thì là.', 'vietnamese', 20, 4, 'easy', 'https://images.unsplash.com/photo-1534939561126-855b8675edd7?auto=format&fit=crop&w=800&q=80', '["Món canh","Hải sản","Thanh mát","Hà Nội","cat:mon_canh","region:bac"]'),
('vn-kho-01', 'thit-kho-trung', 'Thịt kho tàu nước dừa trứng béo ngậy', 'Thịt ba chỉ vuông vức óng ả màu cánh gián, ninh nhừ mềm tan trong nước dừa xiêm cùng trứng gà bùi bùi chuẩn Tết miền Nam.', 'vietnamese', 45, 4, 'medium', 'https://images.unsplash.com/photo-1544025162-d76694265947?auto=format&fit=crop&w=800&q=80', '["Món kho","Món mặn","Nam Bộ","Ăn cơm nhiều","cat:mon_kho","region:nam"]'),
('vn-kho-02', 'ca-loc-kho-to-tieu-den', 'Cá lóc kho tộ tiêu đen cay nồng', 'Thịt cá lóc đồng săn chắc ngấm đậm vị mắm đường, thơm nức tiêu đen xay và tóp mỡ giòn rụm trong niêu đất.', 'vietnamese', 30, 3, 'medium', 'https://images.unsplash.com/photo-1617093727343-374698b1b08d?auto=format&fit=crop&w=800&q=80', '["Món kho","Đặc sản","Đậm đà","Niêu đất","cat:mon_kho","region:nam"]'),
('vn-kho-03', 'ga-ta-kho-gung-sa', 'Gà ta kho gừng sả đậm đà', 'Thịt gà ta da giòn thịt dai ngọt quyện trong lớp sốt kho vàng óng, thơm ấm nồng gừng tươi thái sợi và sả giã dập.', 'vietnamese', 25, 4, 'easy', 'https://images.unsplash.com/photo-1604908176997-125f25cc6f3d?auto=format&fit=crop&w=800&q=80', '["Món kho","Món mặn","Ấm bụng","Mùa đông","cat:mon_kho","region:toan_quoc"]'),
('vn-kho-04', 'suon-heo-xao-chua-ngot', 'Sườn heo xào chua ngọt chuẩn vị', 'Từng dẻ sườn non áo lớp sốt đỏ au chua thanh ngọt dịu từ giấm táo và cà chua, thịt mềm róc xương đậm vị cơm nhà.', 'vietnamese', 30, 4, 'medium', 'https://images.unsplash.com/photo-1529193591184-b1d58069ecdd?auto=format&fit=crop&w=800&q=80', '["Món mặn","Trẻ em thích","Chua ngọt","Đậm đà","cat:mon_kho","region:bac"]'),
('vn-kho-05', 'tom-rim-man-ngot', 'Tôm rim mặn ngọt mắm đường tỏi ớt', 'Tôm đồng hoặc tôm thẻ tươi vỏ giòn giòn, thịt dai ngọt rim kẹo mặn mặn ngọt ngọt, ăn với cơm nóng cực kỳ đưa miệng.', 'vietnamese', 15, 3, 'easy', 'https://images.unsplash.com/photo-1559742811-822873691df8?auto=format&fit=crop&w=800&q=80', '["Món rim","Hải sản","Dưới 20 phút","Đưa cơm","cat:mon_kho","region:toan_quoc"]'),
('vn-kho-06', 'thit-ba-chi-kho-cu-cai', 'Thịt ba chỉ kho củ cải trắng', 'Thịt ba chỉ ngậy béo kho cùng từng khúc củ cải trắng hút trọn vị ngọt mặn tinh túy, mềm tan trong miệng.', 'vietnamese', 35, 4, 'easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?auto=format&fit=crop&w=800&q=80', '["Món kho","Món mặn","Cơm nhà","Mùa đông","cat:mon_kho","region:bac"]'),
('vn-xao-01', 'rau-muong-xao-toi', 'Rau muống xào tỏi xanh giòn', 'Rau muống ngọn non xanh mướt giòn sần sật dậy mùi thơm lừng của tỏi ta phi vàng xém cạnh, linh hồn bữa cơm gia đình.', 'vietnamese', 10, 3, 'easy', 'https://images.unsplash.com/photo-1540420773420-3366772f4999?auto=format&fit=crop&w=800&q=80', '["Món xào","Rau củ","Dưới 20 phút","Nhanh gọn","cat:mon_xao","region:toan_quoc"]'),
('vn-xao-02', 'bo-xao-can-toi-hanh-tay', 'Bò xào cần tỏi hành tây mềm ngọt', 'Thịt bò thăn thái mỏng xào lửa lớn giữ trọn độ mềm mọng nước, kết hợp mùi thơm nồng đặc trưng của cần tây và tỏi tây.', 'vietnamese', 15, 3, 'easy', 'https://images.unsplash.com/photo-1512058564366-18510be2db19?auto=format&fit=crop&w=800&q=80', '["Món xào","Thịt bò","Dưới 20 phút","Bổ dưỡng","cat:mon_xao","region:bac"]'),
('vn-xao-03', 'muc-xao-can-toi-dua', 'Mực ống xào cần tỏi dứa chua ngọt', 'Mực ống tươi dày mình giòn sần sật xào cùng dứa thơm chua dịu, cần tây và ớt chuông đậm đà thanh vị biển.', 'vietnamese', 15, 3, 'medium', 'https://images.unsplash.com/photo-1535400255456-984241443b29?auto=format&fit=crop&w=800&q=80', '["Món xào","Hải sản","Dưới 20 phút","Đãi khách","cat:mon_xao","region:toan_quoc"]'),
('vn-xao-04', 'thit-bo-xao-bong-cai', 'Thịt bò xào bông cải xanh cà rốt', 'Súp lơ xanh giòn mát xào cùng thịt bò mềm và cà rốt tỉa hoa, món xào đầy đặn sắc màu và giàu chất xơ.', 'vietnamese', 15, 3, 'easy', 'https://images.unsplash.com/photo-1543339308-43e59d6b73a6?auto=format&fit=crop&w=800&q=80', '["Món xào","Bổ dưỡng","Healthy","Cơm nhà","cat:mon_xao","region:toan_quoc"]'),
('vn-xao-05', 'su-su-xao-trung-ga', 'Su su xào trứng gà thanh ngọt', 'Su su bào sợi giòn ngọt tự nhiên ôm lấy từng mảng trứng gà vàng ươm béo ngậy, món ăn thanh đạm dễ làm.', 'vietnamese', 12, 3, 'easy', 'https://images.unsplash.com/photo-1565299585323-38d6b0865b47?auto=format&fit=crop&w=800&q=80', '["Món xào","Tiết kiệm","Dưới 20 phút","Thanh đạm","cat:mon_xao","region:bac"]'),
('vn-xao-06', 'dau-cove-xao-thit-bo', 'Đậu cô ve xào thịt bò giòn ngọt', 'Đậu cô ve tước xơ bẻ khúc xào vừa chín tới giữ trọn màu xanh non mướt, kết hợp thịt bò mềm thơm ngất ngây.', 'vietnamese', 15, 3, 'easy', 'https://images.unsplash.com/photo-1550547660-d9450f859349?auto=format&fit=crop&w=800&q=80', '["Món xào","Bò xào","Dưới 20 phút","Cơm nhà","cat:mon_xao","region:toan_quoc"]'),
('vn-chien-01', 'dau-phu-sot-ca-chua', 'Đậu phụ lướt ván sốt cà chua', 'Miếng đậu phụ vàng mềm núng nính phủ lớp sốt cà chua đỏ au sánh mịn quyện cùng hành hoa thơm nức mũi.', 'vietnamese', 15, 3, 'easy', 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?auto=format&fit=crop&w=800&q=80', '["Món chiên","Tiết kiệm","Dưới 20 phút","Quốc dân","cat:mon_chien","region:toan_quoc"]'),
('vn-chien-02', 'trung-chien-thit-bam-nam-rom', 'Trứng chiên thịt bằm nấm rơm', 'Món trứng chiên phồng xốp vàng rực, bên trong đầy đặn thịt heo băm đậm đà và nấm ngọt giòn sần sật.', 'vietnamese', 12, 3, 'easy', 'https://images.unsplash.com/photo-1525351484163-7529414344d8?auto=format&fit=crop&w=800&q=80', '["Món chiên","Nhanh gọn","Dưới 20 phút","Được yêu thích","cat:mon_chien","region:toan_quoc"]'),
('vn-chien-03', 'canh-ga-chien-nuoc-mam', 'Cánh gà chiên nước mắm tỏi ớt', 'Cánh gà chiên vàng giòn rụm bên ngoài mọng nước bên trong, lắc đều cùng sốt mắm tỏi ớt ngọt mặn dính tay hấp dẫn.', 'vietnamese', 25, 4, 'medium', 'https://images.unsplash.com/photo-1527477396000-e27163b481c2?auto=format&fit=crop&w=800&q=80', '["Món chiên","Ăn vặt","Món nhậu","Trẻ em mê","cat:mon_chien","region:toan_quoc"]'),
('vn-chien-04', 'cha-ca-hai-phong', 'Chả cá chiên thì là hạt tiêu', 'Chả cá thác lác hoặc cá điêu hồng quết dẻo quánh, trộn nhiều thì là và hạt tiêu đập dập rán vàng phồng thơm phức.', 'vietnamese', 20, 4, 'medium', 'https://images.unsplash.com/photo-1534766555764-ce878a5e3a2b?auto=format&fit=crop&w=800&q=80', '["Món chiên","Hải sản","Đặc sản","Bắc Bộ","cat:mon_chien","region:bac"]'),
('vn-chien-05', 'nem-ran-truyen-thong-ha-noi', 'Nem rán truyền thống Hà Nội giòn rụm', 'Vỏ nem vàng rộm giòn tan rụm, nhân thịt băm mộc nhĩ nấm hương miến dong và trứng gà thơm phức chấm mắm chua ngọt.', 'vietnamese', 35, 4, 'hard', 'https://images.unsplash.com/photo-1544025162-d76694265947?auto=format&fit=crop&w=800&q=80', '["Món chiên","Nem rán","Tiệc tùng","Truyền thống","cat:mon_chien","region:bac"]'),
('vn-chien-06', 'ca-ro-phi-chien-gion-mam-gung', 'Cá rô phi chiên giòn chấm mắm gừng', 'Cá rô phi làm sạch khía vảy chiên giòn tan từ vây đến da, thịt cá trắng ngọt chấm nước mắm gừng ớt ấm nồng.', 'vietnamese', 25, 4, 'easy', 'https://images.unsplash.com/photo-1519708227418-c8fd9a32b7a2?auto=format&fit=crop&w=800&q=80', '["Món chiên","Cá tươi","Cơm nhà","Dễ làm","cat:mon_chien","region:toan_quoc"]'),
('vn-hap-01', 'ga-ta-hap-la-chanh', 'Gà ta hấp lá chanh da giòn thịt ngọt', 'Gà thả vườn hấp cách thủy giữ nguyên 100% vị ngọt thanh tinh khiết, da gà vàng óng giòn sần sật thơm nức lá chanh thái chỉ.', 'vietnamese', 30, 4, 'medium', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?auto=format&fit=crop&w=800&q=80', '["Món hấp","Gà ta","Thanh đạm","Đãi tiệc","cat:mon_hap_luoc","region:bac"]'),
('vn-hap-02', 'thit-ba-chi-luoc-mam-tom', 'Thịt ba chỉ luộc chấm mắm tôm cà pháo', 'Thịt ba chỉ luộc trắng ngần, nạc mỡ đan xen đều tăm tắp thái mỏng tang, chấm mắm tôm đánh sủi bọt bông và cà pháo muối giòn.', 'vietnamese', 20, 4, 'easy', 'https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80', '["Món luộc","Món thanh","Dưới 20 phút","Kinh điển","cat:mon_hap_luoc","region:bac"]'),
('vn-hap-03', 'ca-dieu-hong-hap-hanh-gung', 'Cá điêu hồng hấp hành gừng xì dầu', 'Cá điêu hồng tươi hấp nguyên con giữ trọn vị ngọt tự nhiên, quyện trong sốt xì dầu thơm nồng gừng sợi và hành hoa chần dầu sôi.', 'vietnamese', 25, 4, 'medium', 'https://images.unsplash.com/photo-1534422298391-e4f8c172dddb?auto=format&fit=crop&w=800&q=80', '["Món hấp","Cá tươi","Tươi ngọt","Đãi khách","cat:mon_hap_luoc","region:toan_quoc"]'),
('vn-hap-04', 'rau-cu-luoc-kho-quet', 'Rau củ luộc thập cẩm kho quẹt tóp mỡ', 'Mẹt rau củ vườn nhà tươi non giòn ngọt chấm ngập trong niêu kho quẹt tóp mỡ tôm khô thơm nức mũi chuẩn vị Nam Bộ.', 'vietnamese', 20, 4, 'easy', 'https://images.unsplash.com/photo-1511690656952-34342bb7c2f2?auto=format&fit=crop&w=800&q=80', '["Món luộc","Rau củ","Kho quẹt","Món Nam","cat:mon_hap_luoc","region:nam"]'),
('vn-hap-05', 'muc-hap-gung-sa', 'Mực ống hấp gừng sả giòn ngọt', 'Mực ống tươi dày mình hấp cùng sả cây đập dập và gừng non, từng miếng mực giòn ngọt sần sật mọng nước.', 'vietnamese', 12, 3, 'easy', 'https://images.unsplash.com/photo-1535400255456-984241443b29?auto=format&fit=crop&w=800&q=80', '["Món hấp","Hải sản","Dưới 20 phút","Tươi ngọt","cat:mon_hap_luoc","region:trung"]'),
('vn-hap-06', 'tom-hap-nuoc-dua-tuoi', 'Tôm hấp nước dừa tươi ngọt lịm', 'Tôm sú tươi roi rói hấp cùng nước dừa xiêm ngọt lịm, vỏ tôm đỏ au thịt tôm săn chắc ngọt ngào hương dừa thanh tao.', 'vietnamese', 12, 3, 'easy', 'https://images.unsplash.com/photo-1559742811-822873691df8?auto=format&fit=crop&w=800&q=80', '["Món hấp","Hải sản","Dưới 20 phút","Đặc sản Nam Bộ","cat:mon_hap_luoc","region:nam"]'),
('vn-cuon-01', 'goi-cuon-tom-thit-nam-bo', 'Gỏi cuốn tôm thịt chấm tương phộng', 'Cuốn bánh tráng trong veo lộ rõ tôm đỏ au, thịt ba chỉ, bún tươi và rau húng quế mát lành, chấm tương đen đậu phộng béo bùi.', 'vietnamese', 20, 4, 'medium', 'https://images.unsplash.com/photo-1534422298391-e4f8c172dddb?auto=format&fit=crop&w=800&q=80', '["Món cuốn","Healthy","Mùa hè","Đặc sản Nam Bộ","cat:mon_cuon_nom","region:nam"]'),
('vn-cuon-02', 'pho-cuon-bo-ha-noi', 'Phở cuốn bò xào rau thơm Hà Nội', 'Bánh phở vuông mềm mượt cuốn gọn thịt bò xào tỏi thơm nức mũi và rau xà lách kinh giới, chấm nước mắm chua ngọt thanh tao.', 'vietnamese', 20, 3, 'easy', 'https://images.unsplash.com/photo-1563379091339-03b21ab4a4f8?auto=format&fit=crop&w=800&q=80', '["Món cuốn","Hà Nội","Phố Trúc Bạch","Dưới 20 phút","cat:mon_cuon_nom","region:bac"]'),
('vn-cuon-03', 'nom-hoa-chuoi-tai-heo', 'Nộm hoa chuối tai heo giòn sần sật', 'Hoa chuối bào mỏng ngâm trắng tinh quyện cùng tai heo luộc giòn sần sật, vị chua ngọt thanh tao cùng lạc rang bùi bùi.', 'vietnamese', 25, 4, 'medium', 'https://images.unsplash.com/photo-1540420773420-3366772f4999?auto=format&fit=crop&w=800&q=80', '["Món nộm","Khai vị","Giòn sần sật","Ăn không ngấy","cat:mon_cuon_nom","region:bac"]'),
('vn-cuon-04', 'goi-ga-xe-phay-bap-cai', 'Gỏi gà xé phay bắp cải hành tây', 'Thịt gà ta luộc xé sợi dai ngọt trộn cùng bắp cải bào mỏng giòn rụm, hành tây chua ngọt dịu và rau răm thơm the the.', 'vietnamese', 20, 4, 'easy', 'https://images.unsplash.com/photo-1512621776951-a57141f2eefd?auto=format&fit=crop&w=800&q=80', '["Món gỏi","Miền Trung","Healthy","Đặc sản","cat:mon_cuon_nom","region:trung"]'),
('vn-cuon-05', 'nom-du-du-bo-kho', 'Nộm đu đủ bò khô phố cổ Hà Nội', 'Sợi đu đủ xanh nạo giòn sần sật hòa quyện nước mắm giấm chua ngọt cay cay, điểm xuyết từng sợi bò khô nâu óng thơm phức.', 'vietnamese', 15, 3, 'easy', 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?auto=format&fit=crop&w=800&q=80', '["Món nộm","Phố Cổ","Ăn vặt","Dưới 20 phút","cat:mon_cuon_nom","region:bac"]'),
('vn-cuon-06', 'nem-lui-hue-nuong-sa', 'Nem lụi nướng sả cuốn bánh tráng', 'Thịt heo xay quết mịn bọc quanh thân cây sả tươi nướng xém cạnh thơm lừng, cuốn bánh tráng rau sống chấm nước lèo bùi ngậy.', 'vietnamese', 30, 4, 'medium', 'https://images.unsplash.com/photo-1529193591184-b1d58069ecdd?auto=format&fit=crop&w=800&q=80', '["Món nướng","Xứ Huế","Món cuốn","Đặc sản","cat:mon_cuon_nom","region:trung"]'),
('vn-bun-01', 'pho-bo-tai-lan-ha-noi', 'Phở bò tái lăn Hà Nội nước dùng trong vắt', 'Thịt bò thăn đảo tái lăn trên chảo lửa ngùn ngụt cùng tỏi gừng, chan nước dùng ninh xương ống thơm hồi quế thảo quả.', 'vietnamese', 35, 4, 'hard', 'https://images.unsplash.com/photo-1582878826629-29b7ad1cdc43?auto=format&fit=crop&w=800&q=80', '["Phở","Hà Nội","Tinh hoa ẩm thực","Bữa sáng / tối","cat:mon_bun_pho","region:bac"]'),
('vn-bun-02', 'bun-cha-ha-noi-than-hoa', 'Bún chả nướng than hoa Hà Nội', 'Chả miếng ba chỉ nướng xém vàng ươm và chả băm viên đậm vị, thả trong bát nước mắm ấm chua ngọt dưa góp đu đủ.', 'vietnamese', 35, 4, 'medium', 'https://images.unsplash.com/photo-1569058242253-92a9c755a0ec?auto=format&fit=crop&w=800&q=80', '["Bún chả","Hà Nội","Đặc sản","Ăn trưa","cat:mon_bun_pho","region:bac"]'),
('vn-bun-03', 'bun-bo-hue-chuan-vi', 'Bún bò xứ Huế giò heo chả cua sả ớt', 'Tô bún bò cay nồng thơm lừng mùi sả phi mắm ruốc, nước dùng ngọt đậm đà từ xương ống cùng bắp bò giòn sần sật.', 'vietnamese', 40, 4, 'hard', 'https://images.unsplash.com/photo-1569718212165-3a8278d5f624?auto=format&fit=crop&w=800&q=80', '["Bún bò","Xứ Huế","Cay nồng","Đậm vị","cat:mon_bun_pho","region:trung"]'),
('vn-bun-04', 'bun-rieu-cua-dong', 'Bún riêu cua đồng bắp bò giấm bỗng', 'Bát bún riêu đỏ cam óng ả với tảng riêu cua đồng béo ngậy, đậu phụ rán giòn, thịt bò tái chần và nước dùng chua dịu giấm bỗng.', 'vietnamese', 30, 4, 'medium', 'https://images.unsplash.com/photo-1552611052-33e04de081de?auto=format&fit=crop&w=800&q=80', '["Bún riêu","Hà Nội","Mùa hè","Cua đồng","cat:mon_bun_pho","region:bac"]'),
('vn-bun-05', 'bun-thit-nuong-nam-bo', 'Bún thịt nướng Nam Bộ chả giò mỡ hành', 'Thịt nướng vỉ thơm lừng mè rang và sả ớt, ăn kèm bún tươi, mỡ hành xanh mướt, đậu phộng rang giòn và nước mắm chua ngọt.', 'vietnamese', 30, 4, 'medium', 'https://images.unsplash.com/photo-1563379091339-03b21ab4a4f8?auto=format&fit=crop&w=800&q=80', '["Bún thịt nướng","Nam Bộ","Ăn trưa","Đưa miệng","cat:mon_bun_pho","region:nam"]'),
('vn-bun-06', 'mien-ga-nam-huong', 'Miến gà nấm hương mộc nhĩ thanh tao', 'Sợi miến dong dai trong vắt nấu trong nước luộc gà ngọt thanh tao, thơm ngát nấm hương rừng và thịt gà xé phay mềm ngọt.', 'vietnamese', 25, 4, 'easy', 'https://images.unsplash.com/photo-1612927601601-6638404737ce?auto=format&fit=crop&w=800&q=80', '["Miến gà","Hà Nội","Thanh đạm","Ấm bụng","cat:mon_bun_pho","region:bac"]'),
('vn-chay-01', 'dau-phu-kho-nam-dong-co', 'Đậu phụ kho nấm đông cô tiêu đen', 'Đậu phụ rán vàng óng kho ngấm đượm sốt tương đen cùng nấm đông cô ngọt bùi, thơm nức tiêu sọ xay cay the ấm nồng.', 'vietnamese', 20, 3, 'easy', 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?auto=format&fit=crop&w=800&q=80', '["Món chay","Thanh lọc","Đậu phụ","Dưới 20 phút","cat:mon_chay","region:toan_quoc"]'),
('vn-chay-02', 'canh-nam-hat-sen-tao-do', 'Canh nấm hạt sen táo đỏ thanh lọc', 'Nước canh trong veo ngọt ngào từ củ quả ninh tự nhiên, hạt sen bở tơi bùi béo cùng các loại nấm tươi bổ dưỡng an thần.', 'vietnamese', 25, 4, 'easy', 'https://images.unsplash.com/photo-1547592180-85f173990554?auto=format&fit=crop&w=800&q=80', '["Món chay","Bổ dưỡng","An thần","Thanh nhiệt","cat:mon_chay","region:toan_quoc"]'),
('vn-chay-03', 'mi-xao-chay-rau-nam', 'Mì xào giòn chay nấm rau củ', 'Sợi mì xào vàng thơm tơi sợi không bết dính, đảo cùng nấm đùi gà dai giòn, cải ngọt và cà rốt ngập tràn sốt dầu hào chay.', 'vietnamese', 15, 3, 'easy', 'https://images.unsplash.com/photo-1585032226651-759b368d7246?auto=format&fit=crop&w=800&q=80', '["Món chay","Mì xào","Dưới 20 phút","Nhanh gọn","cat:mon_chay","region:toan_quoc"]'),
('vn-chay-04', 'ca-tim-nuong-mo-hanh', 'Cà tím nướng mỡ hành nước tương tỏi ớt', 'Cà tím nướng than thơm lừng mùi khói, thịt cà mềm mọng ngọt ngào phủ ngập mỡ hành béo ngậy và nước tương tỏi ớt.', 'vietnamese', 20, 3, 'easy', 'https://images.unsplash.com/photo-1511690656952-34342bb7c2f2?auto=format&fit=crop&w=800&q=80', '["Món chay","Dân dã","Nam Bộ","Ngon miệng","cat:mon_chay","region:nam"]'),
('vn-chay-05', 'dau-hu-non-sot-nam-rom', 'Đậu hũ non sốt nấm rơm dầu hào', 'Từng lát đậu hũ non mềm mịn như lụa tan ngay đầu lưỡi, ngập trong lớp sốt nấm rơm bóng bẩy đậm đà sánh ngậy.', 'vietnamese', 15, 3, 'easy', 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?auto=format&fit=crop&w=800&q=80', '["Món chay","Đậu hũ non","Dưới 20 phút","Mềm mịn","cat:mon_chay","region:toan_quoc"]'),
('vn-chay-06', 'canh-cai-nau-dau-phu-non', 'Canh cải xanh gừng đậu phụ thanh mát', 'Bát canh cải bẹ xanh tươi non nấu cùng gừng tươi đập dập cay nồng và đậu phụ béo mềm, xua tan hàn khí ấm bụng.', 'vietnamese', 12, 4, 'easy', 'https://images.unsplash.com/photo-1547592166-23ac45744acd?auto=format&fit=crop&w=800&q=80', '["Món canh","Món chay","Ấm bụng","Dưới 20 phút","cat:mon_chay","region:toan_quoc"]'),
('vn-sang-01', 'com-chien-trung-toi-hanh-hoa', 'Cơm chiên trứng vàng giòn tỏi phi', 'Hạt cơm nguội vàng óng bọc đều lớp trứng gà bóng bẩy, chiên giòn tơi xốp dậy mùi thơm nức của tỏi phi và hành hoa.', 'vietnamese', 12, 2, 'easy', 'https://images.unsplash.com/photo-1603133872878-684f208fb84b?auto=format&fit=crop&w=800&q=80', '["Ăn sáng","Cơm chiên","Dưới 20 phút","Tiết kiệm","cat:mon_nhanh_sang","region:toan_quoc"]'),
('vn-sang-02', 'banh-mi-op-la-pate', 'Bánh mì ốp la pate dưa leo', 'Ổ bánh mì giòn tan kẹp quả trứng ốp la lòng đào béo ngậy, quét đẫm lớp pate Hải Phòng thơm lừng và dưa leo mát rượi.', 'vietnamese', 10, 2, 'easy', 'https://images.unsplash.com/photo-1626804475297-41608ea09aeb?auto=format&fit=crop&w=800&q=80', '["Bánh mì","Ăn sáng","Dưới 20 phút","Quốc dân","cat:mon_nhanh_sang","region:toan_quoc"]'),
('vn-sang-03', 'chao-thit-bam-gung-tia-to', 'Cháo thịt bằm gừng tía tô giải cảm', 'Bát cháo hoa sánh mịn nấu từ hạt gạo rang thơm, thịt nạc heo băm ngọt lịm cùng lá tía tô và gừng già giải cảm hiệu quả.', 'vietnamese', 20, 3, 'easy', 'https://images.unsplash.com/photo-1547592180-85f173990554?auto=format&fit=crop&w=800&q=80', '["Cháo","Giải cảm","Ăn sáng","Ấm bụng","cat:mon_nhanh_sang","region:toan_quoc"]'),
('vn-sang-04', 'mi-tom-xao-bo-trung-long-dao', 'Mì gói xào bò trứng lòng đào', 'Sợi mì tôm chần xào giòn dai không nát, hòa cùng thịt bò xào mềm ngọt, rau cải giòn mát và quả trứng ốp lòng đào béo ngậy.', 'vietnamese', 15, 2, 'easy', 'https://images.unsplash.com/photo-1569718212165-3a8278d5f624?auto=format&fit=crop&w=800&q=80', '["Mì xào","Ăn nhanh","Dưới 20 phút","Sinh viên","cat:mon_nhanh_sang","region:toan_quoc"]'),
('vn-sang-05', 'trung-cuon-rau-cu-han-quoc', 'Trứng cuộn rau củ mềm mịn', 'Trứng gà đánh mịn cuộn tròn nhiều lớp xen kẽ cà rốt và hành hoa thái hạt lựu xinh xắn, món ăn sáng giàu protein cho cả nhà.', 'vietnamese', 12, 2, 'easy', 'https://images.unsplash.com/photo-1525351484163-7529414344d8?auto=format&fit=crop&w=800&q=80', '["Trứng cuộn","Ăn sáng","Dưới 20 phút","Bé thích","cat:mon_nhanh_sang","region:toan_quoc"]'),
('vn-sang-06', 'sup-ga-ngo-non-nam-huong', 'Súp gà ngô non nấm hương trứng hoa', 'Bát súp nóng hổi sánh óng ánh với những vân trứng hoa bay lượn, thịt gà xé ngọt mềm cùng hạt ngô ngọt giòn bùi.', 'vietnamese', 18, 4, 'easy', 'https://images.unsplash.com/photo-1547592166-23ac45744acd?auto=format&fit=crop&w=800&q=80', '["Súp","Ăn sáng","Dưới 20 phút","Khai vị","cat:mon_nhanh_sang","region:toan_quoc"]'),
('vn-lau-01', 'lau-rieu-cua-dong-bap-bo-suon-sun', 'Lẩu riêu cua đồng sườn sụn bắp bò', 'Nồi lẩu riêu cua bốc khói nghi ngút thơm nồng giấm bỗng, tảng riêu cua vàng ngậy nhúng bắp bò hoa giòn và sườn non sần sật.', 'vietnamese', 45, 6, 'hard', 'https://images.unsplash.com/photo-1547928576-a4a33237cbc3?auto=format&fit=crop&w=800&q=80', '["Món lẩu","Tiệc gia đình","Hà Nội","Cực phẩm","cat:mon_lau_tiec","region:bac"]'),
('vn-lau-02', 'lau-ga-la-giang-chua-cay', 'Lẩu gà ta lá giang chua cay Nam Bộ', 'Thịt gà ta da giòn thịt săn chắc nấu cùng lá giang vò dập chua thanh thanh the mát, làm ấm lòng những ngày mưa.', 'vietnamese', 40, 5, 'medium', 'https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80', '["Món lẩu","Nam Bộ","Gà ta","Chua cay","cat:mon_lau_tiec","region:nam"]'),
('vn-lau-03', 'lau-hai-san-thap-cam-chua-cay', 'Lẩu hải sản tôm mực chua cay', 'Nồi lẩu hải sản ngập tràn tôm sú tươi roi rói, mực ống giòn sần sật, nước dùng Tom Yum chua cay ngọt đậm vị biển.', 'vietnamese', 35, 5, 'medium', 'https://images.unsplash.com/photo-1547928576-a4a33237cbc3?auto=format&fit=crop&w=800&q=80', '["Món lẩu","Hải sản","Chua cay","Tiệc tùng","cat:mon_lau_tiec","region:toan_quoc"]'),
('vn-lau-04', 'lau-nam-thap-cam-thanh-dam', 'Lẩu nấm thập cẩm gà ta thanh đạm bổ dưỡng', 'Nước lẩu hầm từ gà ta và các vị thảo mộc thiên nhiên ngọt lịm, nhúng cùng 6 loại nấm tươi giòn dai thanh lọc cơ thể.', 'vietnamese', 40, 5, 'medium', 'https://images.unsplash.com/photo-1547592180-85f173990554?auto=format&fit=crop&w=800&q=80', '["Món lẩu","Nấm tươi","Bổ dưỡng","Healthy","cat:mon_lau_tiec","region:toan_quoc"]'),
('vn-lau-05', 'lau-ca-thac-lac-kho-qua', 'Lẩu cá thác lác khổ qua thanh mát', 'Chả cá thác lác quết dai dẻo vo viên thả vào nồi nước dùng thanh ngọt, nhúng cùng khổ qua bào mỏng giòn không đắng.', 'vietnamese', 30, 4, 'medium', 'https://images.unsplash.com/photo-1603105037880-880cd4edfb0d?auto=format&fit=crop&w=800&q=80', '["Món lẩu","Đặc sản miền Tây","Khổ qua","Thanh mát","cat:mon_lau_tiec","region:nam"]')
