INSERT INTO recipe_steps (id, recipe_id, step_number, instruction, tip, timer_minutes) VALUES
('vn-canh-01_step_1', 'vn-canh-01', 1, 'Cá lóc làm sạch, xát muối và rượu trắng để khử nhớt và mùi tanh, ướp với chút nước mắm, tiêu trong 10 phút.', 'Khử tanh cá bằng muối hột và nước cốt chanh giúp cá thơm và thịt săn.', NULL),
('vn-canh-01_step_2', 'vn-canh-01', 2, 'Phi thơm tỏi băm với chút dầu ăn, cho cà chua và dứa vào xào sơ để lên màu đẹp và tạo vị chua ngọt tự nhiên.', NULL, NULL),
('vn-canh-01_step_3', 'vn-canh-01', 3, 'Đổ 1 lít nước vào nồi đun sôi, chắt nước cốt me chua vào, thả cá khúc vào nấu sôi 8 phút với lửa vừa.', NULL, 8),
('vn-canh-01_step_4', 'vn-canh-01', 4, 'Vớt bọt thường xuyên để nước canh trong. Cho giá đỗ vào đun sôi thêm 2 phút rồi tắt bếp.', NULL, 2),
('vn-canh-01_step_5', 'vn-canh-01', 5, 'Múc canh ra bát lớn, rắc ngò gai, ngò ôm cắt nhỏ, vài lát ớt và tỏi phi vàng thơm lừng lên trên.', NULL, NULL),
('vn-canh-02_step_1', 'vn-canh-02', 1, 'Nước lọc cua đồng khuấy đều cùng 1 thìa cà phê muối, bắc lên bếp đun với lửa vừa và khuấy nhẹ tay theo một chiều.', NULL, NULL),
('vn-canh-02_step_2', 'vn-canh-02', 2, 'Khi nước canh bắt đầu nóng lăn tăn, hạ lửa thật nhỏ để thịt cua kết lại thành mảng riêu nổi lên mặt.', 'Không khuấy mạnh khi nước gần sôi kẻo làm vỡ mảng gạch cua.', NULL),
('vn-canh-02_step_3', 'vn-canh-02', 3, 'Gạt nhẹ mảng thịt cua sang một bên, thả mướp hương và rau đay, mồng tơi đã rửa sạch cắt khúc vào nồi.', NULL, 3),
('vn-canh-02_step_4', 'vn-canh-02', 4, 'Nêm nước mắm vừa ăn, đun sôi bùng lại 2 phút là rau chín mềm giữ màu xanh mướt.', NULL, 2),
('vn-canh-02_step_5', 'vn-canh-02', 5, 'Múc canh ra bát, khéo léo để tảng riêu cua lên trên, ăn kèm cà pháo muối giòn.', NULL, NULL),
('vn-canh-03_step_1', 'vn-canh-03', 1, 'Khổ qua rửa sạch, rạch một đường dọc thân móc bỏ ruột, chần sơ qua nước sôi 1 phút rồi ngâm nước đá để giảm đắng.', NULL, NULL),
('vn-canh-03_step_2', 'vn-canh-03', 2, 'Trộn thịt xay, mộc nhĩ băm nhỏ, hành tím, nước mắm, tiêu xay thật đều, để 10 phút cho ngấm gia vị.', NULL, NULL),
('vn-canh-03_step_3', 'vn-canh-03', 3, 'Nhồi nhân thịt vào từng trái khổ qua, dùng cọng hành lá trần buộc nhẹ quanh quả để giữ nhân.', NULL, NULL),
('vn-canh-03_step_4', 'vn-canh-03', 4, 'Đun sôi 1 lít nước dùng, thả khổ qua nhồi thịt vào hầm nhỏ lửa trong 20 phút đến khi khổ qua mềm.', NULL, 20),
('vn-canh-03_step_5', 'vn-canh-03', 5, 'Nêm nếm lại vừa miệng, rắc hành ngò thái nhỏ và tiêu hạt đập dập lên trên.', NULL, NULL),
('vn-canh-04_step_1', 'vn-canh-04', 1, 'Sườn non chặt khúc 3cm, chần qua nước sôi cùng chút muối để loại bỏ bọt bẩn, rửa sạch lại.', NULL, NULL),
('vn-canh-04_step_2', 'vn-canh-04', 2, 'Phi thơm hành củ băm, cho sườn vào xào săn với 1 thìa nước mắm.', NULL, NULL),
('vn-canh-04_step_3', 'vn-canh-04', 3, 'Thêm 1.2 lít nước vào nồi, hầm lửa nhỏ liu riu trong 20 phút cho sườn mềm nhừ.', NULL, 20),
('vn-canh-04_step_4', 'vn-canh-04', 4, 'Cho bí đao vào nấu thêm 5 phút đến khi bí trong là chín tới, giữ được độ giòn ngọt.', NULL, 5),
('vn-canh-04_step_5', 'vn-canh-04', 5, 'Tắt bếp, thêm hành hoa mùi tàu thái nhỏ và rắc chút tiêu cay nồng.', NULL, NULL),
('vn-canh-05_step_1', 'vn-canh-05', 1, 'Thịt bằm ướp 1 thìa cà phê nước mắm, hành tím băm và chút tiêu bột trong 5 phút.', NULL, NULL),
('vn-canh-05_step_2', 'vn-canh-05', 2, 'Đặt nồi lên bếp, phi thơm hành tím với chút dầu ăn rồi trút thịt vào xào tơi săn lại.', NULL, NULL),
('vn-canh-05_step_3', 'vn-canh-05', 3, 'Đổ 800ml nước vào đun sôi, thả bí đỏ vào nấu sôi vừa trong 10 phút cho bí chín mềm bùi.', NULL, 10),
('vn-canh-05_step_4', 'vn-canh-05', 4, 'Nêm lại gia vị cho vừa miệng, dùng muôi dầm nhẹ vài miếng bí để nước canh có độ sánh vàng đẹp mắt.', NULL, NULL),
('vn-canh-05_step_5', 'vn-canh-05', 5, 'Múc canh ra tô, rắc ngò gai thái sợi lên trên và thưởng thức nóng.', NULL, NULL),
('vn-canh-06_step_1', 'vn-canh-06', 1, 'Ngao ngâm nước vo gạo và ớt cắt lát 30 phút cho nhả sạch cát, rửa sạch vỏ.', NULL, NULL),
('vn-canh-06_step_2', 'vn-canh-06', 2, 'Luộc ngao với 800ml nước đến khi ngao vừa há miệng thì vớt ra, gỡ lấy thịt, gạn lấy nước luộc trong.', NULL, 5),
('vn-canh-06_step_3', 'vn-canh-06', 3, 'Phi thơm hành củ, xào cà chua cho nhuyễn rồi trút thịt ngao vào đảo nhanh tay cùng 1 thìa nước mắm.', NULL, NULL),
('vn-canh-06_step_4', 'vn-canh-06', 4, 'Đổ nước luộc ngao và dứa vào nồi đun sôi bùng, nêm nếm lại vừa vị chua thanh ngọt.', NULL, 4),
('vn-canh-06_step_5', 'vn-canh-06', 5, 'Cho hành hoa, thì là cắt khúc vào nồi rồi tắt bếp ngay để giữ màu xanh và hương thơm thì là.', NULL, NULL),
('vn-kho-01_step_1', 'vn-kho-01', 1, 'Thịt ba chỉ cạo sạch bì, cắt miếng vuông lớn 4x4cm, chần sơ nước sôi rồi để ráo.', NULL, NULL),
('vn-kho-01_step_2', 'vn-kho-01', 2, 'Ướp thịt với nước mắm ngon, hành tỏi băm, tiêu và 1 thìa đường trong 30 phút cho ngấm sâu.', 'Ướp thịt với chút nước cốt chanh giúp phần mỡ khi kho trong veo và giòn.', NULL),
('vn-kho-01_step_3', 'vn-kho-01', 3, 'Luộc trứng gà chín tới, ngâm nước lạnh bóc sạch vỏ.', NULL, 8),
('vn-kho-01_step_4', 'vn-kho-01', 4, 'Đảo săn thịt rồi đổ nước dừa xiêm ngập mặt thịt, đun sôi rồi hạ lửa nhỏ liu riu không đậy nắp trong 30 phút.', NULL, 30),
('vn-kho-01_step_5', 'vn-kho-01', 5, 'Thả trứng luộc vào kho cùng thêm 15 phút đến khi nước thịt sánh kẹo, màu vàng ươm cánh gián đẹp mắt.', NULL, 15),
('vn-kho-02_step_1', 'vn-kho-02', 1, 'Cá lóc làm sạch ruột, xát muối khử tanh rồi ướp nước mắm, nước màu dừa, tiêu đen đập dập 20 phút.', NULL, NULL),
('vn-kho-02_step_2', 'vn-kho-02', 2, 'Cho thịt ba chỉ vào nồi đất đảo lấy mỡ giòn, phi thơm hành tím và đầu hành lá.', NULL, NULL),
('vn-kho-02_step_3', 'vn-kho-02', 3, 'Xếp từng khứa cá vào tộ đất, đun lửa lớn 3 phút cho miếng cá săn chắc hai mặt.', NULL, NULL),
('vn-kho-02_step_4', 'vn-kho-02', 4, 'Thêm nửa chén nước sôi ấm và vài trái ớt hiểm, đậy nắp kho liu riu nhỏ lửa 20 phút.', NULL, 20),
('vn-kho-02_step_5', 'vn-kho-02', 5, 'Mở nắp, rưới nước sốt lên mặt cá đến khi cạn sánh sệt, rắc nhiều tiêu đen xay và hành lá ăn kèm cơm cháy.', NULL, NULL),
('vn-kho-03_step_1', 'vn-kho-03', 1, 'Gà chặt miếng vừa ăn, chần qua nước sôi gừng để sạch mùi hôi lông, để ráo.', NULL, NULL),
('vn-kho-03_step_2', 'vn-kho-03', 2, 'Ướp thịt gà cùng nước mắm, nửa lượng gừng sợi, chút tiêu và đường trong 15 phút.', NULL, NULL),
('vn-kho-03_step_3', 'vn-kho-03', 3, 'Đun nóng dầu ăn, phi vàng thơm sả băm và phần gừng sợi còn lại.', NULL, NULL),
('vn-kho-03_step_4', 'vn-kho-03', 4, 'Cho thịt gà vào đảo đều tay trên lửa lớn cho miếng gà săn chắc và ngấm vị vàng thơm.', NULL, 5),
('vn-kho-03_step_5', 'vn-kho-03', 5, 'Châm thêm 50ml nước sôi, hạ nhỏ lửa đậy vung kho 15 phút đến khi nước kho sền sệt bám đều thịt gà.', NULL, 15),
('vn-kho-04_step_1', 'vn-kho-04', 1, 'Sườn non chặt miếng 3-4cm, luộc sơ qua nước sôi rồi ướp chút hạt nêm và nước mắm 10 phút.', NULL, NULL),
('vn-kho-04_step_2', 'vn-kho-04', 2, 'Cho dầu vào chảo rán sườn lửa vừa đến khi bề mặt xém vàng giòn hai mặt rồi vớt ra ráo dầu.', NULL, 8),
('vn-kho-04_step_3', 'vn-kho-04', 3, 'Pha nước sốt: 2 thìa nước mắm, 2 thìa giấm gạo, 2 thìa đường, 1 thìa tương cà khuấy tan.', NULL, NULL),
('vn-kho-04_step_4', 'vn-kho-04', 4, 'Phi thơm tỏi băm, xào nhuyễn cà chua và hành tây rồi đổ nước sốt pha sẵn vào đun sôi.', NULL, NULL),
('vn-kho-04_step_5', 'vn-kho-04', 5, 'Trút sườn đã rán vào đảo đều cho sốt quánh lại, ngấm đều phủ bóng khắp các miếng sườn.', NULL, 5),
('vn-kho-05_step_1', 'vn-kho-05', 1, 'Tôm rửa sạch, cắt bỏ râu và đuôi nhọn, để ráo nước hoàn toàn.', NULL, NULL),
('vn-kho-05_step_2', 'vn-kho-05', 2, 'Đặt chảo lên bếp, cho 1 thìa đường vào thắng nước màu cánh gián, phi thơm tỏi băm.', NULL, NULL),
('vn-kho-05_step_3', 'vn-kho-05', 3, 'Bật lửa lớn, trút tôm vào đảo nhanh tay đến khi tôm cong lại và chuyển màu đỏ cam tươi rói.', NULL, 3),
('vn-kho-05_step_4', 'vn-kho-05', 4, 'Nêm nước mắm và chút đường, rim nhỏ lửa đến khi nước sốt keo lại bám đều quanh vỏ tôm.', NULL, 5),
('vn-kho-05_step_5', 'vn-kho-05', 5, 'Rắc hành lá thái nhỏ và tiêu hạt giã dập, tắt bếp trút ra đĩa.', NULL, NULL),
('vn-kho-06_step_1', 'vn-kho-06', 1, 'Thịt ba chỉ thái miếng con chì vừa ăn, ướp với nước mắm, hành tím băm, tiêu xay 15 phút.', NULL, NULL),
('vn-kho-06_step_2', 'vn-kho-06', 2, 'Củ cải trắng gọt vỏ, cắt khúc dày 2cm, xóc chút muối hột 5 phút rồi rửa sạch để giảm vị hăng.', NULL, NULL),
('vn-kho-06_step_3', 'vn-kho-06', 3, 'Xào săn thịt ba chỉ cho ra bớt mỡ và thịt hơi xém cạnh vàng ươm.', NULL, NULL),
('vn-kho-06_step_4', 'vn-kho-06', 4, 'Cho củ cải vào đảo cùng 2 phút, thêm nước sôi xâm xấp mặt thịt, kho lửa nhỏ trong 20 phút.', NULL, 20),
('vn-kho-06_step_5', 'vn-kho-06', 5, 'Khi củ cải trong mềm và nước kho sánh sệt thì tắt bếp, rắc hành lá cắt khúc lên mặt.', NULL, NULL),
('vn-xao-01_step_1', 'vn-xao-01', 1, 'Rau muống nhặt bỏ lá già và gốc cứng, ngâm nước muối loãng rồi rửa sạch vớt ra rổ thưa.', NULL, NULL),
('vn-xao-01_step_2', 'vn-xao-01', 2, 'Đun một nồi nước thật sôi với chút muối, chần nhanh rau trong 30 giây rồi vớt thả ngay vào âu nước đá lạnh.', 'Sốc nhiệt nước đá giúp rau giữ màu xanh lục bảo và độ giòn sần sật.', NULL),
('vn-xao-01_step_3', 'vn-xao-01', 3, 'Đặt chảo sâu lòng lên bếp lửa lớn, cho dầu ăn vào phi thơm 2/3 lượng tỏi đập dập đến khi vàng ruộm.', NULL, NULL),
('vn-xao-01_step_4', 'vn-xao-01', 4, 'Thả rau muống vào xào đảo nhanh tay trên lửa cực lớn trong 1.5 phút cùng nước mắm.', NULL, 2),
('vn-xao-01_step_5', 'vn-xao-01', 5, 'Cho nốt phần tỏi tươi còn lại vào đảo đều thêm 10 giây rồi trút ngay ra đĩa.', NULL, NULL),
('vn-xao-02_step_1', 'vn-xao-02', 1, 'Thịt bò thái mỏng ngang thớ, ướp với tỏi băm, xì dầu, tiêu và 1 thìa dầu ăn để thịt không bị khô dai.', NULL, NULL),
('vn-xao-02_step_2', 'vn-xao-02', 2, 'Làm nóng chảo với lửa lớn, phi thơm tỏi rồi cho thịt bò vào đảo nhanh tay 1 phút đến khi tái thì trút ra đĩa riêng.', NULL, 1),
('vn-xao-02_step_3', 'vn-xao-02', 3, 'Vẫn chiếc chảo đó, thêm chút dầu xào hành tây và cà chua trong 2 phút cho vừa chín tới.', NULL, NULL),
('vn-xao-02_step_4', 'vn-xao-02', 4, 'Trút đĩa thịt bò trở lại chảo, đảo đều tay cùng rau củ trên lửa lớn trong 30 giây.', NULL, NULL),
('vn-xao-02_step_5', 'vn-xao-02', 5, 'Rắc hạt tiêu cay nồng, bày ra đĩa ăn nóng với cơm.', NULL, NULL),
('vn-xao-03_step_1', 'vn-xao-03', 1, 'Mực làm sạch nang mực, khứa vảy rồng trên thân rồi cắt miếng vuông, chần nhanh qua nước sôi có rượu gừng khử tanh.', NULL, NULL),
('vn-xao-03_step_2', 'vn-xao-03', 2, 'Phi thơm tỏi gừng băm, cho mực vào xào lửa lớn trong 1.5 phút cho mực săn giòn nở hoa rồi múc ra đĩa.', NULL, 2),
('vn-xao-03_step_3', 'vn-xao-03', 3, 'Xào dứa, cà chua và hành tây với lửa vừa cho tiết nước chua ngọt tự nhiên.', NULL, NULL),
('vn-xao-03_step_4', 'vn-xao-03', 4, 'Trút mực vào đảo đều cùng rau củ, nêm nước mắm và tiêu xay vừa khẩu vị.', NULL, NULL),
('vn-xao-03_step_5', 'vn-xao-03', 5, 'Rắc cần tây cắt khúc đảo nhanh 15 giây rồi tắt bếp.', NULL, NULL),
('vn-xao-04_step_1', 'vn-xao-04', 1, 'Thịt bò ướp với tỏi băm, 1 thìa dầu hào, tiêu và chút dầu ăn trong 10 phút.', NULL, NULL),
('vn-xao-04_step_2', 'vn-xao-04', 2, 'Bông cải và cà rốt chần sơ qua nước sôi 1 phút để giữ màu tươi và độ giòn ngọt.', NULL, NULL),
('vn-xao-04_step_3', 'vn-xao-04', 3, 'Phi tỏi thơm trên chảo nóng, cho thịt bò vào xào chín tái trong 1 phút rồi gắp riêng ra.', NULL, NULL),
('vn-xao-04_step_4', 'vn-xao-04', 4, 'Cho bông cải xanh và cà rốt vào xào nhanh với 1 thìa dầu hào và 2 thìa nước lọc trong 2 phút.', NULL, NULL),
('vn-xao-04_step_5', 'vn-xao-04', 5, 'Đổ thịt bò vào đảo chung 30 giây cho hòa quyện hương vị, rắc tiêu và múc ra đĩa.', NULL, NULL),
('vn-xao-05_step_1', 'vn-xao-05', 1, 'Su su gọt vỏ rửa sạch mủ, bào thành sợi dài.', NULL, NULL),
('vn-xao-05_step_2', 'vn-xao-05', 2, 'Đánh tan 2 quả trứng gà cùng 1 thìa cà phê nước mắm và chút tiêu.', NULL, NULL),
('vn-xao-05_step_3', 'vn-xao-05', 3, 'Phi thơm hành tím với dầu ăn, cho su su vào xào lửa lớn trong 3 phút cho chín tới.', NULL, NULL),
('vn-xao-05_step_4', 'vn-xao-05', 4, 'Rưới trứng gà đánh tan đều khắp chảo su su, để 15 giây cho trứng se lại rồi dùng đũa đảo nhẹ tay.', NULL, NULL),
('vn-xao-05_step_5', 'vn-xao-05', 5, 'Rắc hành hoa và tiêu xay, tắt bếp thưởng thức nóng.', NULL, NULL),
('vn-xao-06_step_1', 'vn-xao-06', 1, 'Đậu cô ve tước xơ 2 bên sườn, cắt vát chéo, rửa sạch.', NULL, NULL),
('vn-xao-06_step_2', 'vn-xao-06', 2, 'Thịt bò thái mỏng ướp tỏi băm, hạt tiêu và dầu ăn.', NULL, NULL),
('vn-xao-06_step_3', 'vn-xao-06', 3, 'Xào nhanh thịt bò trên lửa lớn trong 1 phút rồi múc ra đĩa.', NULL, NULL),
('vn-xao-06_step_4', 'vn-xao-06', 4, 'Phi thêm tỏi, cho đậu cô ve vào xào với lửa lớn, thêm chút xíu nước để đậu chín giòn đều trong 3 phút.', NULL, NULL),
('vn-xao-06_step_5', 'vn-xao-06', 5, 'Đổ thịt bò vào đảo lại 30 giây, nêm nếm gia vị và rắc tiêu thơm.', NULL, NULL),
('vn-chien-01_step_1', 'vn-chien-01', 1, 'Đậu phụ cắt miếng vuông vừa ăn, thấm khô nước bằng khăn giấy sạch.', NULL, NULL),
('vn-chien-01_step_2', 'vn-chien-01', 2, 'Đun nóng chảo dầu, chiên lướt ván đậu phụ đến khi vỏ ngoài vàng giòn rụm nhưng bên trong vẫn mềm béo.', NULL, 6),
('vn-chien-01_step_3', 'vn-chien-01', 3, 'Phi thơm đầu hành trắng, cho cà chua thái hạt lựu vào xào nhuyễn cùng nước mắm và chút nước.', NULL, NULL),
('vn-chien-01_step_4', 'vn-chien-01', 4, 'Thả đậu phụ vào đảo nhẹ tay cho lớp sốt cà chua ngấm đều quanh từng miếng đậu trong 3 phút.', NULL, NULL),
('vn-chien-01_step_5', 'vn-chien-01', 5, 'Rắc hành lá thái nhỏ và tiêu thơm, múc ra đĩa ăn kèm cơm nóng hổi.', NULL, NULL),
('vn-chien-02_step_1', 'vn-chien-02', 1, 'Xào sơ thịt bằm và nấm băm cùng hành khô cho chín tới và ráo bớt nước.', NULL, NULL),
('vn-chien-02_step_2', 'vn-chien-02', 2, 'Đập 4 quả trứng gà vào tô, nêm nước mắm, tiêu và hành hoa rồi đánh bông nhẹ.', NULL, NULL),
('vn-chien-02_step_3', 'vn-chien-02', 3, 'Trộn đều phần thịt bằm nấm đã xào vào âu trứng.', NULL, NULL),
('vn-chien-02_step_4', 'vn-chien-02', 4, 'Đun nóng dầu trong chảo, đổ trứng vào dàn đều, đậy vung chiên lửa nhỏ 4 phút cho chín phồng đáy.', NULL, 4),
('vn-chien-02_step_5', 'vn-chien-02', 5, 'Khéo léo lật mặt trứng chiên thêm 2 phút cho vàng đều hai mặt rồi cắt miếng tam giác.', NULL, NULL),
('vn-chien-03_step_1', 'vn-chien-03', 1, 'Cánh gà rửa sạch với nước muối gừng, khía nhẹ 2 đường ở mặt trong để nhanh chín và ngấm vị.', NULL, NULL),
('vn-chien-03_step_2', 'vn-chien-03', 2, 'Chiên cánh gà ngập dầu với lửa vừa đến khi da gà giòn rụm và ngả màu vàng cánh gián thì vớt ra thấm dầu.', NULL, 12),
('vn-chien-03_step_3', 'vn-chien-03', 3, 'Pha sốt nước mắm: 2 thìa mắm, 2 thìa đường, 1 thìa nước lọc, chút tiêu khuấy tan.', NULL, NULL),
('vn-chien-03_step_4', 'vn-chien-03', 4, 'Phi thơm tỏi và ớt băm trên chảo với 1 thìa dầu, đổ sốt nước mắm vào đun sôi sủi bọt keo lại.', NULL, NULL),
('vn-chien-03_step_5', 'vn-chien-03', 5, 'Trút cánh gà chiên vào đảo nhanh tay 1 phút để sốt mắm óng ánh phủ đều quanh cánh gà.', NULL, NULL),
('vn-chien-04_step_1', 'vn-chien-04', 1, 'Thịt cá thấm khô, xay nhuyễn rồi dùng thìa quết mạnh tay liên tục 10 phút để chả đạt độ dai giòn tự nhiên.', NULL, NULL),
('vn-chien-04_step_2', 'vn-chien-04', 2, 'Trộn mỡ heo hạt lựu, thì là thái nhỏ, hành tím, nước mắm, tiêu sọ đập dập vào khối chả cá.', NULL, NULL),
('vn-chien-04_step_3', 'vn-chien-04', 3, 'Thoa chút dầu ăn lên lòng bàn tay, nặn chả cá thành từng miếng tròn dẹt vừa ăn.', NULL, NULL),
('vn-chien-04_step_4', 'vn-chien-04', 4, 'Đun nóng dầu, thả từng miếng chả cá vào chiên lửa vừa cho phồng xốp vàng ruộm hai mặt.', NULL, 8),
('vn-chien-04_step_5', 'vn-chien-04', 5, 'Gắp chả cá ra đĩa lót giấy thấm dầu, ăn nóng chấm tương ớt hoặc nước mắm gừng thì là.', NULL, NULL),
('vn-chien-05_step_1', 'vn-chien-05', 1, 'Trộn đều thịt xay, tôm, mộc nhĩ, nấm hương, cà rốt, miến dong cắt khúc, hành hoa và lòng đỏ trứng gà.', NULL, NULL),
('vn-chien-05_step_2', 'vn-chien-05', 2, 'Trải bánh đa nem ra đĩa phẳng, cho lượng nhân vừa phải vào cuốn tròn vừa tay không quá chặt kẻo bục nem.', NULL, NULL),
('vn-chien-05_step_3', 'vn-chien-05', 3, 'Chiên nem 2 lần lửa: Lần 1 chiên chín tới ở lửa nhỏ vừa rồi vớt ra để nguội.', NULL, 10),
('vn-chien-05_step_4', 'vn-chien-05', 4, 'Lần 2: Trước khi ăn chiên lại trên lửa lớn 2 phút để vỏ nem giòn rụm lâu và không bị ngậm dầu.', NULL, 3),
('vn-chien-05_step_5', 'vn-chien-05', 5, 'Bày ra đĩa cùng rau sống kinh giới tía tô, chấm nước mắm pha chua ngọt tỏi ớt cà rốt đu đủ muối.', NULL, NULL),
('vn-chien-06_step_1', 'vn-chien-06', 1, 'Cá rô phi làm sạch màng đen trong bụng, khía vát sâu lên thân, lau thật khô ráo cả trong lẫn ngoài.', NULL, NULL),
('vn-chien-06_step_2', 'vn-chien-06', 2, 'Đun dầu ăn sôi già, thả cá vào chiên vàng giòn một mặt rồi mới nhẹ nhàng lật sang mặt còn lại.', NULL, 15),
('vn-chien-06_step_3', 'vn-chien-06', 3, 'Pha nước mắm chấm: 2 thìa nước mắm, 1 thìa đường, gừng giã nhuyễn, tỏi ớt băm và nước cốt chanh khuấy đều.', NULL, NULL),
('vn-chien-06_step_4', 'vn-chien-06', 4, 'Cá chín vàng giòn rụm cả 2 mặt thì vớt ra gác lên rây cho ráo dầu.', NULL, NULL),
('vn-chien-06_step_5', 'vn-chien-06', 5, 'Thưởng thức khi cá còn nóng hổi giòn rụm cùng cơm và rau luộc.', NULL, NULL),
('vn-hap-01_step_1', 'vn-hap-01', 1, 'Gà làm sạch xát muối và gừng đập dập quanh da để khử sạch mùi hôi, rửa lại để ráo.', NULL, NULL),
('vn-hap-01_step_2', 'vn-hap-01', 2, 'Xếp một lớp sả đập dập và gừng thái lát dưới đáy xửng hấp, đặt gà lên trên.', NULL, NULL),
('vn-hap-01_step_3', 'vn-hap-01', 3, 'Đậy kín nắp xửng hấp cách thủy trên lửa vừa trong 25 phút đến khi dùng tăm chọc không còn ứa nước hồng.', NULL, 25),
('vn-hap-01_step_4', 'vn-hap-01', 4, 'Gà chín vớt ra ngâm ngay vào âu nước đá lạnh 3 phút rồi vớt ra để da gà se giòn căng mọng.', NULL, NULL),
('vn-hap-01_step_5', 'vn-hap-01', 5, 'Chặt gà thành từng miếng vuông đẹp mắt, rắc nhiều lá chanh thái chỉ lên trên, chấm muối tiêu chanh ớt.', NULL, NULL),
('vn-hap-02_step_1', 'vn-hap-02', 1, 'Thịt ba chỉ rửa sạch, dùng dây dù buộc nhẹ cuộn tròn để miếng thịt luộc thái ra tròn đẹp.', NULL, NULL),
('vn-hap-02_step_2', 'vn-hap-02', 2, 'Đun nồi nước sôi lăn tăn cùng củ hành tím và gừng đập dập, thả miếng thịt vào luộc lửa vừa.', NULL, 15),
('vn-hap-02_step_3', 'vn-hap-02', 3, 'Vớt thịt ngâm ngay vào thau nước đá lạnh có vắt chút nước cốt chanh để thịt trắng phau và bì giòn.', 'Ngâm nước đá sau luộc giúp giữ độ mọng nước và không bị thâm bì.', NULL),
('vn-hap-02_step_4', 'vn-hap-02', 4, 'Thịt nguội hẳn dùng dao thật sắc thái lát mỏng tang xếp đều ra đĩa.', NULL, NULL),
('vn-hap-02_step_5', 'vn-hap-02', 5, 'Pha mắm chấm chanh tỏi ớt đánh bông bọt trắng, ăn kèm rau húng quế và dưa chuột.', NULL, NULL),
('vn-hap-03_step_1', 'vn-hap-03', 1, 'Cá mổ sạch vẩy và mang, khía 3 đường chéo trên thân, ướp chút hạt nêm và gừng sợi trong bụng cá.', NULL, NULL),
('vn-hap-03_step_2', 'vn-hap-03', 2, 'Đặt cá vào đĩa sâu lòng, rải một nửa gừng sợi lên trên rồi cho vào xửng hấp chín tới trong 18 phút.', NULL, 18),
('vn-hap-03_step_3', 'vn-hap-03', 3, 'Pha sốt xì dầu: 3 thìa xì dầu, 1 thìa dầu hào, 1 thìa đường và 2 thìa nước lọc đun sôi lăn tăn.', NULL, NULL),
('vn-hap-03_step_4', 'vn-hap-03', 4, 'Rải hành hoa chẻ sợi và gừng tươi còn lại lên khắp mình cá, đun dầu ăn thật sôi rồi xối trực tiếp lên hành gừng để dậy mùi thơm nức.', NULL, NULL),
('vn-hap-03_step_5', 'vn-hap-03', 5, 'Rưới nước sốt xì dầu quanh thân cá, dọn lên bàn ăn nóng kèm bánh tráng cuốn rau sống.', NULL, NULL),
('vn-hap-04_step_1', 'vn-hap-04', 1, 'Thịt ba chỉ thái hạt lựu đảo trên chảo nhỏ lấy tóp mỡ vàng giòn, vớt tóp ra riêng.', NULL, NULL),
('vn-hap-04_step_2', 'vn-hap-04', 2, 'Dùng mỡ đó phi thơm hành tỏi băm, cho tôm khô vào xào thơm.', NULL, NULL),
('vn-hap-04_step_3', 'vn-hap-04', 3, 'Pha 3 thìa nước mắm ngon và 2 thìa đường vào chảo, đun nhỏ lửa đến khi mắm keo sền sệt thì thả tóp mỡ, ớt hiểm và tiêu sọ vào.', NULL, 8),
('vn-hap-04_step_4', 'vn-hap-04', 4, 'Đun sôi nồi nước với chút muối, lần lượt luộc chín tới cà rốt, su su và bông cải xanh rồi vớt ra đĩa.', NULL, NULL),
('vn-hap-04_step_5', 'vn-hap-04', 5, 'Bày mẹt rau củ xanh mướt quanh niêu kho quẹt bốc khói nghi ngút.', NULL, NULL),
('vn-hap-05_step_1', 'vn-hap-05', 1, 'Mực rút túi mực và xương sống mềm, rửa sạch để ráo.', NULL, NULL),
('vn-hap-05_step_2', 'vn-hap-05', 2, 'Lót sả cây đập dập dưới đáy đĩa hấp, xếp mực lên trên, rải gừng non và ớt sừng khắp thân mực.', NULL, NULL),
('vn-hap-05_step_3', 'vn-hap-05', 3, 'Đặt vào xửng nước sôi hấp cách thủy với lửa lớn trong đúng 8 phút để mực chín giòn ngọt không bị dai.', NULL, 8),
('vn-hap-05_step_4', 'vn-hap-05', 4, 'Cắt mực thành từng khoanh tròn vừa ăn xếp lại ngay ngắn trên đĩa.', NULL, NULL),
('vn-hap-05_step_5', 'vn-hap-05', 5, 'Chấm cùng muối ớt tiêu chanh hoặc mù tạt xì dầu đậm vị.', NULL, NULL),
('vn-hap-06_step_1', 'vn-hap-06', 1, 'Tôm cắt bớt râu và chân bơi, rửa sạch để ráo.', NULL, NULL),
('vn-hap-06_step_2', 'vn-hap-06', 2, 'Đổ 1 bát nước dừa tươi vào nồi cùng sả đập dập, đun sôi bùng lên.', NULL, NULL),
('vn-hap-06_step_3', 'vn-hap-06', 3, 'Thả tôm vào đảo đều và đậy nắp hấp trong 6 phút đến khi tôm cong đều chuyển màu đỏ rực.', NULL, 6),
('vn-hap-06_step_4', 'vn-hap-06', 4, 'Gắp tôm ra đĩa sâu lòng, xếp quanh quả dừa tươi hoặc trang trí cùng hành hoa.', NULL, NULL),
('vn-hap-06_step_5', 'vn-hap-06', 5, 'Thưởng thức nóng chấm muối tiêu chanh ớt ngọt lịm từng thớ thịt.', NULL, NULL),
('vn-cuon-01_step_1', 'vn-cuon-01', 1, 'Tôm luộc chín bóc vỏ chẻ đôi sống lưng. Thịt ba chỉ luộc chín tới thái lát mỏng vừa.', NULL, NULL),
('vn-cuon-01_step_2', 'vn-cuon-01', 2, 'Thấm ướt nhẹ bánh tráng dẻo, đặt xà lách, rau thơm và một lọn bún tươi lên bánh.', NULL, NULL),
('vn-cuon-01_step_3', 'vn-cuon-01', 3, 'Xếp thịt ba chỉ vào trong, gấp mép bánh 2 bên lại rồi đặt 2-3 nửa con tôm mặt đỏ hướng ra ngoài cùng nhánh hẹ dài ló ra.', NULL, NULL),
('vn-cuon-01_step_4', 'vn-cuon-01', 4, 'Cuộn tròn chặt tay để thấy rõ lớp tôm thịt đẹp mắt qua lớp bánh tráng trong veo.', NULL, NULL),
('vn-cuon-01_step_5', 'vn-cuon-01', 5, 'Pha sốt chấm: Xào tỏi với tương đen bơ đậu phộng cho sánh mịn, rắc đậu phộng rang giã dập và ớt băm.', NULL, NULL),
('vn-cuon-02_step_1', 'vn-cuon-02', 1, 'Thịt bò ướp tỏi băm, tiêu xay và nước mắm 10 phút.', NULL, NULL),
('vn-cuon-02_step_2', 'vn-cuon-02', 2, 'Xào thịt bò trên chảo lửa cực lớn trong 1 phút cho thịt chín tới mềm mọng, không bị ra nước.', NULL, NULL),
('vn-cuon-02_step_3', 'vn-cuon-02', 3, 'Trải từng lá bánh phở vuông ra đĩa, đặt xà lách, rau thơm kinh giới và thịt bò xào lên trên.', NULL, NULL),
('vn-cuon-02_step_4', 'vn-cuon-02', 4, 'Cuộn tròn đều tay thành từng cuốn phở thon dài trắng ngần.', NULL, NULL),
('vn-cuon-02_step_5', 'vn-cuon-02', 5, 'Bày ra đĩa, chấm cùng nước mắm chua ngọt pha tỏi ớt cà rốt đu đủ giòn.', NULL, NULL),
('vn-cuon-03_step_1', 'vn-cuon-03', 1, 'Tai heo luộc cùng chút dấm gừng trong 15 phút, vớt ngâm nước đá rồi thái lát thật mỏng.', NULL, 15),
('vn-cuon-03_step_2', 'vn-cuon-03', 2, 'Hoa chuối bào mỏng ngâm vào nước pha chanh muối loãng 15 phút để không bị thâm đen, vớt vắt ráo nước.', NULL, NULL),
('vn-cuon-03_step_3', 'vn-cuon-03', 3, 'Pha nước trộn nộm: 3 thìa nước mắm, 3 thìa đường, 3 thìa nước cốt chanh, tỏi ớt băm khuấy tan.', NULL, NULL),
('vn-cuon-03_step_4', 'vn-cuon-03', 4, 'Cho hoa chuối, tai heo, cà rốt, giá đỗ và rau răm vào âu lớn, rưới nước sốt trộn đều tay.', NULL, NULL),
('vn-cuon-03_step_5', 'vn-cuon-03', 5, 'Để 5 phút cho ngấm, chắt bớt nước nộm, rắc lạc rang giã dập lên trên trước khi dọn đĩa.', NULL, NULL),
('vn-cuon-04_step_1', 'vn-cuon-04', 1, 'Thịt gà luộc xé miếng dài vừa ăn. Bắp cải rửa sạch bào thật mỏng để ráo nước.', NULL, NULL),
('vn-cuon-04_step_2', 'vn-cuon-04', 2, 'Hành tây thái mỏng ngâm nước đá có pha chút giấm 10 phút để hết hăng và giữ độ giòn tan.', NULL, NULL),
('vn-cuon-04_step_3', 'vn-cuon-04', 3, 'Pha sốt trộn: 2 thìa mắm ngon, 2 thìa đường, 2 thìa cốt chanh, ớt băm và chút tiêu xay.', NULL, NULL),
('vn-cuon-04_step_4', 'vn-cuon-04', 4, 'Trộn đều thịt gà xé, bắp cải, hành tây cùng nước sốt trong âu lớn khoảng 3 phút.', NULL, NULL),
('vn-cuon-04_step_5', 'vn-cuon-04', 5, 'Thêm rau răm thái nhỏ và hành phi giòn, bày ra đĩa ăn kèm phồng tôm giòn rụm.', NULL, NULL),
('vn-cuon-05_step_1', 'vn-cuon-05', 1, 'Đu đủ xanh và cà rốt nạo sợi dài, ngâm nước muối loãng 10 phút rồi vắt ráo để sợi nộm giòn tan.', NULL, NULL),
('vn-cuon-05_step_2', 'vn-cuon-05', 2, 'Pha nước trộn nộm chua ngọt chuẩn vị phố cổ: Giấm gạo thơm, đường cát, nước mắm và ớt tươi băm.', NULL, NULL),
('vn-cuon-05_step_3', 'vn-cuon-05', 3, 'Bốc một nắm sợi đu đủ cà rốt đặt vào đĩa sâu lòng.', NULL, NULL),
('vn-cuon-05_step_4', 'vn-cuon-05', 4, 'Rải bò khô xé sợi, rau kinh giới, rau húng thái khúc và lạc rang giã vỡ lên trên.', NULL, NULL),
('vn-cuon-05_step_5', 'vn-cuon-05', 5, 'Rưới đều nước giấm mắm chua ngọt trước khi thưởng thức, trộn đều tay và cảm nhận vị giòn sần sật.', NULL, NULL),
('vn-cuon-06_step_1', 'vn-cuon-06', 1, 'Trộn giò sống và thịt xay cùng hành tỏi băm, nước mắm, mật ong, tiêu sọ, quết đều tay 10 phút cho dẻo quánh.', NULL, NULL),
('vn-cuon-06_step_2', 'vn-cuon-06', 2, 'Cây sả bóc bớt vỏ già, thoa dầu ăn lên tay lấy lượng thịt vừa đủ bọc quanh đầu cây sả.', NULL, NULL),
('vn-cuon-06_step_3', 'vn-cuon-06', 3, 'Nướng nem trên than hoa hoặc nồi chiên không dầu ở 180°C trong 15 phút, trở mặt cho vàng đều xém cạnh.', NULL, 15),
('vn-cuon-06_step_4', 'vn-cuon-06', 4, 'Pha nước lèo chấm Huế: Gan heo băm nhỏ xào với tương đậu phộng và mè rang sánh đặc.', NULL, NULL),
('vn-cuon-06_step_5', 'vn-cuon-06', 5, 'Dùng bánh tráng cuốn nem lụi cùng rau sống, chuối chát, dưa leo chấm ngập nước lèo bùi béo.', NULL, NULL),
('vn-bun-01_step_1', 'vn-bun-01', 1, 'Nước dùng ninh xương ống bò cùng gừng nướng, hành củ nướng, hồi quế trong nhiều giờ, vớt bọt liên tục để nước trong veo.', NULL, NULL),
('vn-bun-01_step_2', 'vn-bun-01', 2, 'Thịt bò thái mỏng ngang thớ, ướp với tỏi băm, gừng và chút xíu nước mắm tiêu.', NULL, NULL),
('vn-bun-01_step_3', 'vn-bun-01', 3, 'Làm nóng chảo với lửa lớn, cho thịt bò vào xào tái lăn nhanh trong 45 giây cho dậy mùi thơm xém cạnh.', NULL, 1),
('vn-bun-01_step_4', 'vn-bun-01', 4, 'Chần bánh phở qua nước sôi xếp vào tô, đặt thịt bò xào tái lăn lên trên cùng đầu hành hoa chẻ.', NULL, NULL),
('vn-bun-01_step_5', 'vn-bun-01', 5, 'Chan nước dùng đang sôi sùng sục ngập bánh phở, rắc hành ngò thái nhỏ và vắt chanh ớt thưởng thức.', NULL, NULL),
('vn-bun-02_step_1', 'vn-bun-02', 1, 'Ướp chả miếng và chả viên với nước mắm, mật ong, nước hàng, hành tỏi băm và tiêu xay 20 phút.', NULL, NULL),
('vn-bun-02_step_2', 'vn-bun-02', 2, 'Viên chả băm thành từng miếng tròn dẹt, kẹp vỉ nướng than hoa cùng chả miếng đến khi mỡ xèo xèo vàng xém thơm nức.', NULL, 15),
('vn-bun-02_step_3', 'vn-bun-02', 3, 'Làm dưa góp: Cà rốt và đu đủ thái lát mỏng ngâm giấm đường muối giòn tan.', NULL, NULL),
('vn-bun-02_step_4', 'vn-bun-02', 4, 'Pha nước chấm bún chả: Nước sôi ấm, nước mắm, giấm thanh, đường theo tỉ lệ 5:1:1:1 ấm nóng.', NULL, NULL),
('vn-bun-02_step_5', 'vn-bun-02', 5, 'Thả chả nướng nóng hổi và dưa góp vào bát nước mắm, ăn kèm bún tươi và đĩa rau sống tía tô kinh giới.', NULL, NULL),
('vn-bun-03_step_1', 'vn-bun-03', 1, 'Ninh xương heo và bắp bò cùng bó sả đập dập, hớt bọt kỹ để nước dùng trong ngọt đậm.', NULL, 30),
('vn-bun-03_step_2', 'vn-bun-03', 2, 'Mắm ruốc Huế khuấy tan với nước lạnh để lắng cặn, chắt lấy nước trong trút vào nồi nước dùng.', NULL, NULL),
('vn-bun-03_step_3', 'vn-bun-03', 3, 'Phi thơm dầu màu điều với sả băm, tỏi băm và ớt bột cho vào nồi để tạo màu đỏ cam hấp dẫn.', NULL, NULL),
('vn-bun-03_step_4', 'vn-bun-03', 4, 'Chần bún sợi to vào tô, xếp bắp bò thái mỏng, khoanh giò heo và chả lụa lên trên.', NULL, NULL),
('vn-bun-03_step_5', 'vn-bun-03', 5, 'Chan nước dùng đang sôi lăn tăn, rắc hành tây thái mỏng, hoa chuối bào sợi và vắt chanh thưởng thức.', NULL, NULL),
('vn-bun-04_step_1', 'vn-bun-04', 1, 'Đun nước lọc cua với chút muối trên lửa vừa, hạ nhỏ lửa khi sôi để mảng riêu cua kết tảng nổi lên bề mặt.', NULL, NULL),
('vn-bun-04_step_2', 'vn-bun-04', 2, 'Vớt mảng riêu cua ra bát riêng để không bị nát vỡ.', NULL, NULL),
('vn-bun-04_step_3', 'vn-bun-04', 3, 'Xào cà chua với chút dầu màu điều rồi trút vào nồi nước cua, thêm giấm bỗng nếp chua thanh tao.', NULL, 5),
('vn-bun-04_step_4', 'vn-bun-04', 4, 'Cho đậu rán vàng vào nồi nước dùng đun sôi nhỏ lửa cho ngấm vị.', NULL, NULL),
('vn-bun-04_step_5', 'vn-bun-04', 5, 'Cho bún vào tô, thêm riêu cua, thịt bò chần tái, đậu rán, chan nước dùng cà chua nóng hổi rắc hành hoa lên trên.', NULL, NULL),
('vn-bun-05_step_1', 'vn-bun-05', 1, 'Thịt thái lát mỏng ướp sả băm, tỏi băm, nước mắm, mật ong, dầu hào và mè trắng 30 phút.', NULL, NULL),
('vn-bun-05_step_2', 'vn-bun-05', 2, 'Nướng thịt trên than hoa hoặc lò nướng 200°C trong 12 phút đến khi thịt vàng óng xém cạnh.', NULL, 12),
('vn-bun-05_step_3', 'vn-bun-05', 3, 'Hành lá thái nhỏ cho vào chén với chút muối, xối dầu ăn đun thật sôi vào làm mỡ hành xanh ngắt.', NULL, NULL),
('vn-bun-05_step_4', 'vn-bun-05', 4, 'Xếp rau sống, dưa leo băm và bún tươi vào tô lớn, gắp thịt nướng nóng hổi lên trên.', NULL, NULL),
('vn-bun-05_step_5', 'vn-bun-05', 5, 'Rưới mỡ hành, đồ chua và rắc đậu phộng rang, chan nước mắm chua ngọt trộn đều thưởng thức.', NULL, NULL),
('vn-bun-06_step_1', 'vn-bun-06', 1, 'Miến dong ngâm nước ấm 10 phút cho mềm rồi cắt khúc vừa ăn.', NULL, NULL),
('vn-bun-06_step_2', 'vn-bun-06', 2, 'Nấm hương ngâm nở rửa sạch, xào sơ với chút nước mắm và đầu hành phi cho thơm ngậy.', NULL, NULL),
('vn-bun-06_step_3', 'vn-bun-06', 3, 'Đun sôi nước luộc gà, trút nấm hương vào nấu trong 5 phút để nước dùng thơm mùi nấm.', NULL, 5),
('vn-bun-06_step_4', 'vn-bun-06', 4, 'Chần miến vào nồi nước dùng 1 phút rồi vớt ra tô, xếp thịt gà xé phay lên trên.', NULL, NULL),
('vn-bun-06_step_5', 'vn-bun-06', 5, 'Chan nước dùng gà nóng hổi ngập miến, rắc hành hoa rau răm và hạt tiêu cay thơm.', NULL, NULL),
('vn-chay-01_step_1', 'vn-chay-01', 1, 'Đậu phụ cắt vuông chiên vàng giòn các mặt. Nấm đông cô ngâm nở cắt chân khía chữ thập trên mũ.', NULL, NULL),
('vn-chay-01_step_2', 'vn-chay-01', 2, 'Phi thơm boa-rô trên chảo, cho nấm vào xào sơ cho săn thơm.', NULL, NULL),
('vn-chay-01_step_3', 'vn-chay-01', 3, 'Pha sốt kho: 3 thìa nước tương, 1 thìa dầu hào chay, 1 thìa đường và nửa chén nước lọc.', NULL, NULL),
('vn-chay-01_step_4', 'vn-chay-01', 4, 'Xếp đậu phụ và nấm vào nồi đất, đổ nước sốt kho lửa nhỏ trong 12 phút đến khi nước keo sánh.', NULL, 12),
('vn-chay-01_step_5', 'vn-chay-01', 5, 'Rưới 1 thìa dầu mè thơm và rắc nhiều tiêu đen xay lên trên, dùng nóng với cơm trắng.', NULL, NULL),
('vn-chay-02_step_1', 'vn-chay-02', 1, 'Hạt sen thông tâm ngâm mềm. Cà rốt và củ quả gọt vỏ cắt miếng vừa ăn.', NULL, NULL),
('vn-chay-02_step_2', 'vn-chay-02', 2, 'Đun sôi 1 lít nước, cho hạt sen và bắp ngọt vào hầm nhỏ lửa 15 phút cho tiết vị ngọt thanh.', NULL, 15),
('vn-chay-02_step_3', 'vn-chay-02', 3, 'Cho cà rốt và các loại nấm tươi vào nấu thêm 5 phút cho nấm chín giòn ngọt.', NULL, 5),
('vn-chay-02_step_4', 'vn-chay-02', 4, 'Nêm chút muối hột và hạt nêm chay nấm cho vừa vị ngọt dịu thanh tao.', NULL, NULL),
('vn-chay-02_step_5', 'vn-chay-02', 5, 'Múc canh ra tô sứ, rắc ngò gai thái nhỏ lên trên và thưởng thức nóng.', NULL, NULL),
('vn-chay-03_step_1', 'vn-chay-03', 1, 'Mì chần qua nước sôi 1 phút rồi xả ngay nước lạnh, trộn chút dầu ăn để sợi mì tơi giòn.', NULL, NULL),
('vn-chay-03_step_2', 'vn-chay-03', 2, 'Phi thơm hành boa-rô, cho nấm đùi gà vào xào lửa lớn cho xém cạnh thơm nức.', NULL, NULL),
('vn-chay-03_step_3', 'vn-chay-03', 3, 'Cho cải ngọt và cà rốt vào đảo chung trong 2 phút với 1 thìa xì dầu.', NULL, NULL),
('vn-chay-03_step_4', 'vn-chay-03', 4, 'Trút sợi mì vào chảo, rưới sốt dầu hào chay đảo đều tay trên lửa lớn 2 phút.', NULL, 2),
('vn-chay-03_step_5', 'vn-chay-03', 5, 'Rắc hạt tiêu thơm lừng và trút ra đĩa thưởng thức ngay khi còn nóng.', NULL, NULL),
('vn-chay-04_step_1', 'vn-chay-04', 1, 'Cà tím để nguyên cuống rửa sạch, dùng nĩa xăm vài lỗ nhỏ trên thân quả.', NULL, NULL),
('vn-chay-04_step_2', 'vn-chay-04', 2, 'Nướng cà tím trên than hoa hoặc nồi chiên không dầu ở 190°C trong 15 phút đến khi vỏ cháy xém mềm nhũn.', NULL, 15),
('vn-chay-04_step_3', 'vn-chay-04', 3, 'Lột sạch lớp vỏ cháy bên ngoài, xếp phần thịt cà trắng mềm ra đĩa, dùng dĩa tước nhẹ thành dải dài.', NULL, NULL),
('vn-chay-04_step_4', 'vn-chay-04', 4, 'Hành hoa thái nhỏ xối dầu nóng làm mỡ hành xanh mướt, rải đều lên khắp thân cà tím.', NULL, NULL),
('vn-chay-04_step_5', 'vn-chay-04', 5, 'Rưới nước tương pha tỏi ớt đường chua ngọt, rắc thêm đậu phộng rang giã dập lên trên.', NULL, NULL),
('vn-chay-05_step_1', 'vn-chay-05', 1, 'Đậu hũ non cắt khoanh tròn dày 1.5cm, xếp ra đĩa sâu lòng đem hấp cách thủy 5 phút cho nóng ấm.', NULL, NULL),
('vn-chay-05_step_2', 'vn-chay-05', 2, 'Nấm rơm cạo sạch chân nấm ngâm nước muối 10 phút rồi vớt ráo.', NULL, NULL),
('vn-chay-05_step_3', 'vn-chay-05', 3, 'Phi thơm boa-rô, cho nấm rơm vào xào lửa lớn trong 2 phút.', NULL, NULL),
('vn-chay-05_step_4', 'vn-chay-05', 4, 'Hòa sốt gồm: 2 thìa dầu hào chay, 1 thìa xì dầu, 1 thìa bột bắp và 4 thìa nước đổ vào chảo đun sánh lại.', NULL, 3),
('vn-chay-05_step_5', 'vn-chay-05', 5, 'Rưới nước sốt nấm rơm đang sôi lục bục phủ đều lên đĩa đậu hũ non, rắc tiêu thơm và ngò rí.', NULL, NULL),
('vn-chay-06_step_1', 'vn-chay-06', 1, 'Cải xanh rửa sạch, cắt khúc 3cm để ráo. Đậu phụ cắt miếng vuông nhỏ.', NULL, NULL),
('vn-chay-06_step_2', 'vn-chay-06', 2, 'Đun sôi 800ml nước, thả gừng già đập dập vào đun sôi 2 phút cho dậy mùi cay thơm.', NULL, 2),
('vn-chay-06_step_3', 'vn-chay-06', 3, 'Thả đậu phụ vào nấu sôi lăn tăn, nêm muối và hạt nêm chay vừa miệng.', NULL, NULL),
('vn-chay-06_step_4', 'vn-chay-06', 4, 'Cho rau cải xanh vào ấn chìm xuống nước, đun sôi bùng lại trong 1.5 phút để rau vừa chín giữ màu xanh mướt.', NULL, NULL),
('vn-chay-06_step_5', 'vn-chay-06', 5, 'Múc canh ra tô ăn nóng, vị đắng nhẹ của cải hòa cùng gừng cay ấm áp.', NULL, NULL),
('vn-sang-01_step_1', 'vn-sang-01', 1, 'Đập 1 quả trứng gà vào tô cơm nguội, dùng bao tay bóp nhẹ để lòng đỏ trứng bao bọc đều từng hạt cơm.', NULL, NULL),
('vn-sang-01_step_2', 'vn-sang-01', 2, 'Đun nóng dầu ăn trên chảo lớn, cho tỏi băm vào phi vàng giòn thơm nức rồi vớt 1 nửa ra để riêng.', NULL, NULL),
('vn-sang-01_step_3', 'vn-sang-01', 3, 'Đập quả trứng còn lại vào chảo đảo tơi thành các vụn trứng vàng óng.', NULL, NULL),
('vn-sang-01_step_4', 'vn-sang-01', 4, 'Trút cơm vào chảo đảo liên tục trên lửa lớn trong 5 phút đến khi hạt cơm săn lại nhảy tanh tách.', NULL, 5),
('vn-sang-01_step_5', 'vn-sang-01', 5, 'Rưới nước mắm quanh thành chảo cho dậy mùi thơm khói, rắc hành lá và tỏi phi giòn lên trên.', NULL, NULL),
('vn-sang-02_step_1', 'vn-sang-02', 1, 'Làm nóng chảo, cho chút bơ vào đun chảy rồi đập trứng gà vào ốp la lòng đào trong 2 phút.', NULL, 2),
('vn-sang-02_step_2', 'vn-sang-02', 2, 'Rạch dọc ổ bánh mì, nướng sơ qua chảo hoặc lò nướng cho vỏ giòn rụm.', NULL, NULL),
('vn-sang-02_step_3', 'vn-sang-02', 3, 'Quết một lớp pate gan mịn màng béo ngậy vào ruột bánh.', NULL, NULL),
('vn-sang-02_step_4', 'vn-sang-02', 4, 'Kẹp trứng ốp la vào giữa, xếp dưa leo, ngò rí tươi mát lên trên.', NULL, NULL),
('vn-sang-02_step_5', 'vn-sang-02', 5, 'Rưới chút xì dầu và tương ớt cay nồng rồi thưởng thức ngay lúc nóng giòn rụm.', NULL, NULL),
('vn-sang-03_step_1', 'vn-sang-03', 1, 'Gạo rang thơm nấu cùng 1 lít nước sôi trong 15 phút đến khi hạt gạo nở bung sánh mịn.', NULL, 15),
('vn-sang-03_step_2', 'vn-sang-03', 2, 'Thịt bằm ướp hành tím, nước mắm và hạt tiêu xào săn thơm.', NULL, NULL),
('vn-sang-03_step_3', 'vn-sang-03', 3, 'Trút thịt bằm và gừng thái chỉ vào nồi cháo đang sôi khuấy đều tay trong 3 phút.', NULL, NULL),
('vn-sang-03_step_4', 'vn-sang-03', 4, 'Lót hành hoa và tía tô thái sợi dưới đáy bát sứ.', NULL, NULL),
('vn-sang-03_step_5', 'vn-sang-03', 5, 'Múc cháo nóng sôi sục lên trên, rắc nhiều tiêu đen xay làm toát mồ hôi giải cảm sảng khoái.', NULL, NULL),
('vn-sang-04_step_1', 'vn-sang-04', 1, 'Mì tôm trụng qua nước sôi 1 phút vớt ra ngay, xả nước lạnh trộn chút dầu ăn để sợi mì tơi dai.', NULL, NULL),
('vn-sang-04_step_2', 'vn-sang-04', 2, 'Phi thơm tỏi, xào thịt bò trên lửa lớn trong 1 phút rồi múc riêng ra đĩa.', NULL, NULL),
('vn-sang-04_step_3', 'vn-sang-04', 3, 'Xào rau cải chín tới, cho mì vào đảo nhanh tay cùng gói gia vị mì và 1 thìa xì dầu.', NULL, 2),
('vn-sang-04_step_4', 'vn-sang-04', 4, 'Cho thịt bò trở lại chảo đảo đều 30 giây rồi trút ra đĩa.', NULL, NULL),
('vn-sang-04_step_5', 'vn-sang-04', 5, 'Đặt quả trứng ốp la lòng đào lên trên, rạch nhẹ để lòng đỏ béo ngậy tan chảy quyện vào sợi mì.', NULL, NULL),
('vn-sang-05_step_1', 'vn-sang-05', 1, 'Đập trứng ra âu cùng 20ml sữa tươi, cà rốt băm, hành hoa và 1 thìa nước mắm, đánh tan đều.', NULL, NULL),
('vn-sang-05_step_2', 'vn-sang-05', 2, 'Quết một lớp dầu mỏng lên chảo chống dính, đun lửa nhỏ vừa rồi đổ một lớp trứng mỏng tráng đều đáy chảo.', NULL, NULL),
('vn-sang-05_step_3', 'vn-sang-05', 3, 'Khi mặt trứng se lại, dùng đũa cuộn tròn dần về một góc chảo.', NULL, NULL),
('vn-sang-05_step_4', 'vn-sang-05', 4, 'Kéo cuộn trứng lại, đổ tiếp lớp trứng mới vào nối tiếp, lặp lại quá trình cuộn tròn dày dặn.', NULL, 6),
('vn-sang-05_step_5', 'vn-sang-05', 5, 'Lấy cuộn trứng ra thớt để nguội 2 phút rồi cắt khoanh tròn 1.5cm xếp ra đĩa.', NULL, NULL),
('vn-sang-06_step_1', 'vn-sang-06', 1, 'Ức gà luộc chín xé sợi mỏng. Giữ lại nước luộc gà ngọt thơm làm nước súp.', NULL, NULL),
('vn-sang-06_step_2', 'vn-sang-06', 2, 'Đun sôi nước luộc gà, cho ngô non ngọt và nấm hương thái chỉ vào nấu trong 5 phút.', NULL, 5),
('vn-sang-06_step_3', 'vn-sang-06', 3, 'Hòa 2 thìa bột bắp với nước lọc, từ từ rót vào nồi súp khuấy đều một chiều đến khi sánh mịn óng ả.', NULL, NULL),
('vn-sang-06_step_4', 'vn-sang-06', 4, 'Đánh tan trứng gà, đổ qua rây vào nồi súp đang sôi đồng thời khuấy nhẹ tay để tạo các vân hoa trứng tuyệt đẹp.', NULL, NULL),
('vn-sang-06_step_5', 'vn-sang-06', 5, 'Múc súp ra bát, rắc ngò rí và tiêu sọ trắng thơm ấm nóng.', NULL, NULL),
('vn-lau-01_step_1', 'vn-lau-01', 1, 'Sườn sụn chần nước sôi rồi ninh nhỏ lửa 25 phút để sườn mềm giòn sần sật.', NULL, 25),
('vn-lau-01_step_2', 'vn-lau-01', 2, 'Nấu nước lọc cua đồng tạo mảng riêu cua lớn, vớt riêu ra đĩa riêng.', NULL, NULL),
('vn-lau-01_step_3', 'vn-lau-01', 3, 'Phi thơm hành khô với dầu màu điều, xào cà chua rồi trút vào nồi nước dùng cùng giấm bỗng thơm nức.', NULL, NULL),
('vn-lau-01_step_4', 'vn-lau-01', 4, 'Đổ nước sườn sụn vào hòa cùng nước riêu cua, nêm gia vị vừa vị chua thanh ngọt béo.', NULL, NULL),
('vn-lau-01_step_5', 'vn-lau-01', 5, 'Đặt nồi lẩu lên bếp từ, thả đậu rán và mảng riêu cua vào, nhúng bắp bò, sườn sụn và rau muống chẻ ăn kèm bún.', NULL, NULL),
('vn-lau-02_step_1', 'vn-lau-02', 1, 'Gà chặt miếng vừa ăn, ướp với sả băm, tỏi, ớt hiểm, nước mắm trong 20 phút.', NULL, NULL),
('vn-lau-02_step_2', 'vn-lau-02', 2, 'Phi thơm tỏi và sả cây đập dập, cho thịt gà vào xào săn chắc đều các mặt.', NULL, NULL),
('vn-lau-02_step_3', 'vn-lau-02', 3, 'Đổ 1.5 lít nước vào hầm gà lửa nhỏ trong 20 phút cho gà chín mềm ngọt nước.', NULL, 20),
('vn-lau-02_step_4', 'vn-lau-02', 4, 'Lá giang rửa sạch, dùng tay vò nhẹ cho dập lá rồi thả vào nồi nước dùng đun sôi 3 phút cho tiết vị chua dịu thanh.', NULL, NULL),
('vn-lau-02_step_5', 'vn-lau-02', 5, 'Nêm lại nước mắm vừa ăn, nhúng ngò gai ngò ôm và bún tươi thưởng thức nóng hổi.', NULL, NULL),
('vn-lau-03_step_1', 'vn-lau-03', 1, 'Hải sản sơ chế sạch sẽ, tôm bỏ chỉ lưng, mực khía bông, cá thái mỏng xếp lên đĩa cùng nấm tươi.', NULL, NULL),
('vn-lau-03_step_2', 'vn-lau-03', 2, 'Phi thơm sả cây, tỏi gừng và ớt băm với chút dầu ăn, xào thơm cà chua và dứa.', NULL, NULL),
('vn-lau-03_step_3', 'vn-lau-03', 3, 'Đổ 1.8 lít nước hầm xương vào đun sôi bùng, vắt nước cốt chanh me và lá chanh vò dập tạo hương thơm lừng.', NULL, 10),
('vn-lau-03_step_4', 'vn-lau-03', 4, 'Nêm nếm nước dùng chua chua cay cay hài hòa đậm đà.', NULL, NULL),
('vn-lau-03_step_5', 'vn-lau-03', 5, 'Đặt lên bàn tiệc, nhúng tôm, mực, cá và nấm kim châm ăn liền khi vừa chín tới để cảm nhận độ giòn ngọt mọng nước.', NULL, NULL),
('vn-lau-04_step_1', 'vn-lau-04', 1, 'Gà ta rửa sạch chần sơ nước sôi, cho vào nồi ninh cùng bắp ngọt và cà rốt 25 phút để lấy nước dùng ngọt thanh.', NULL, 25),
('vn-lau-04_step_2', 'vn-lau-04', 2, 'Các loại nấm tươi cắt bỏ gốc bẩn, rửa nhẹ tay với nước muối loãng rồi xếp ra khay lớn.', NULL, NULL),
('vn-lau-04_step_3', 'vn-lau-04', 3, 'Nêm nếm nước lẩu thanh đạm với muối khoáng và hạt nêm nấm, không dùng quá nhiều gia vị cay nồng.', NULL, NULL),
('vn-lau-04_step_4', 'vn-lau-04', 4, 'Bày nồi lẩu ra giữa bàn, thả đậu hũ non và một phần nấm hương vào đun sôi.', NULL, NULL),
('vn-lau-04_step_5', 'vn-lau-04', 5, 'Nhúng các loại nấm tươi vào nước lẩu sôi trong 2 phút rồi vớt ra ăn ngay giữ trọn vị giòn ngọt thanh tao.', NULL, NULL),
('vn-lau-05_step_1', 'vn-lau-05', 1, 'Cá thác lác nêm nước mắm, hành hoa, tiêu sọ trắng, quết liên tục 15 phút đến khi chả cá dẻo dính chặt vào tô.', NULL, NULL),
('vn-lau-05_step_2', 'vn-lau-05', 2, 'Khổ qua bào lát mỏng tang, ngâm vào thau nước đá lạnh 15 phút để khổ qua giòn rụm và bớt đắng.', NULL, NULL),
('vn-lau-05_step_3', 'vn-lau-05', 3, 'Nấu nước dùng từ xương heo ngọt trong, nêm nếm gia vị thanh dịu.', NULL, NULL),
('vn-lau-05_step_4', 'vn-lau-05', 4, 'Dùng muỗng múc từng viên chả cá thác lác thả vào nồi lẩu sôi, khi viên chả nổi lên là chín tới phồng to.', NULL, NULL),
('vn-lau-05_step_5', 'vn-lau-05', 5, 'Gắp khổ qua nhúng nhanh vào nồi lẩu 10 giây rồi vớt ra ăn liền cùng chả cá dai ngọt và bún tươi.', NULL, NULL)
